-- OFFSET/LIMIT (Slow at high offsets)
SELECT * FROM orders ORDER BY created_at DESC LIMIT 50 OFFSET 100000;

-- Keyset/Cursor Pagination (Fast, index-friendly)
SELECT * FROM orders WHERE created_at < '2023-10-01 12:00:00' AND id < 98765 
ORDER BY created_at DESC, id DESC LIMIT 50;
